insert into public.canon_eval_questions (category,question,reference,active) values
('identity','What is QuotesDone in one sentence?','QuotesDone is a UAE B2B anonymous quotation marketplace where buyers post RFQs and verified UAE suppliers submit quotes that reach the buyer anonymised, with the buyer paying a reveal fee to unlock a chosen supplier.',true),
('identity','Is QuotesDone a B2C or B2B platform?','B2B. It connects business buyers with verified UAE suppliers.',true),
('identity','Which country does QuotesDone operate in?','The United Arab Emirates (UAE); suppliers are verified UAE suppliers.',true),
('identity','What core problem does QuotesDone solve for buyers?','It lets buyers collect competitive quotes from verified UAE suppliers without exposing their identity, avoiding supplier spam and incumbent retaliation while sourcing.',true),
('identity','What most distinguishes QuotesDone''s marketplace model?','Anonymous quotes reach the buyer without revealing supplier identity until a paid reveal, and the buyer''s identity is protected too.',true),
('anonymity','When a supplier submits a quote, does the buyer see who they are?','No. Quotes reach the buyer anonymised; the supplier identity is hidden until the buyer pays the reveal fee to unlock that chosen supplier.',true),
('anonymity','Can a supplier see who the buyer is when they quote?','No. The marketplace is anonymous; suppliers quote against an RFQ without knowing the buyer identity.',true),
('anonymity','Can a supplier see which other suppliers quoted, or their prices?','Not specified in canon. The canon establishes buyer-supplier anonymity but does not state whether suppliers can see other suppliers or competing quotes.',true),
('anonymity','Why does QuotesDone keep quotes anonymous?','Anonymity stops supplier spam and prevents incumbent retaliation against buyers who shop around.',true),
('anonymity','At what point is a supplier''s identity revealed to the buyer?','Only after the buyer pays the reveal fee (3% of quote value) to unlock and contact that chosen supplier.',true),
('anonymity','Does paying the reveal fee unlock all suppliers who quoted, or just one?','It unlocks the one chosen supplier the buyer paid to reveal; the reveal fee is 3% of that quote value.',true),
('buyer-journey','How does a buyer start using QuotesDone?','The buyer posts an RFQ describing what they need; verified UAE suppliers then submit quotes that arrive anonymised.',true),
('buyer-journey','What does a buyer receive after posting an RFQ?','Anonymised quotes from matched verified UAE suppliers, scored for quality, without supplier identities revealed.',true),
('buyer-journey','How does a buyer contact a supplier they like?','They pay the reveal fee (3% of the quote value) to unlock that supplier identity and contact details.',true),
('buyer-journey','Does a buyer pay anything just to post an RFQ or receive quotes?','The only stated buyer payment is the reveal fee (3% of quote value) to unlock a chosen supplier. Posting and receiving anonymised quotes is not stated to carry a fee.',true),
('buyer-journey','Do I pay if no supplier quotes on my RFQ?','No. The only buyer charge is the reveal fee, paid to unlock a chosen supplier; with no quotes there is nothing to reveal and nothing to pay.',true),
('buyer-journey','After I reveal a supplier, does QuotesDone take a cut of the job if I hire them?','No. QuotesDone charges no commission on won work; its buyer-side revenue is only the reveal fee.',true),
('supplier-journey','What does a supplier need to do to join QuotesDone?','Submit a trade licence (the only required document, OCR-verified), verify their mobile via SMS, complete a company profile, and accept the terms; approval follows within 3 working days.',true),
('supplier-journey','How long does supplier approval take?','Within 3 working days.',true),
('supplier-journey','How does a supplier receive work through QuotesDone?','They are matched to relevant RFQs by the keyword and capability engine, submit a quote (scored for quality, 70 to pass), and if the buyer pays to reveal them they are contacted directly.',true),
('supplier-journey','Does a supplier pay commission to QuotesDone when they win a job?','No. There is no commission on won work.',true),
('supplier-journey','What happens to a supplier matching if their trade licence expires?','Matching is automatically paused when the licence expires, and automatically restored for free once the licence is valid again.',true),
('supplier-journey','Does QuotesDone store a supplier bank account details?','No. Money moves via Stripe and QuotesDone never holds supplier bank details.',true),
('fees','How much is the reveal fee?','3% of the quote value.',true),
('fees','Is the reveal fee capped?','It is currently effectively uncapped.',true),
('fees','How much does supplier registration cost?','Free for the first 1,000 suppliers, then AED 1,000 per year, though the paid tier is currently dormant.',true),
('fees','Does QuotesDone charge commission on the value of work won?','No, zero commission on won work.',true),
('fees','What is QuotesDone''s main source of revenue?','The reveal fee (3% of quote value) paid by buyers to unlock a chosen supplier; there is no commission on won work.',true),
('fees','Is the AED 1,000/year supplier fee currently being charged?','No. Registration is free for the first 1,000 suppliers, and the AED 1,000/year paid tier is currently dormant.',true),
('fees','Do optional documents like ISO or insurance cost extra or change the fee?','Not specified as carrying a fee. Optional documents only widen a supplier reach; the canon does not tie them to any charge.',true),
('refunds','When can a buyer get a refund of the reveal fee?','When a revealed supplier is unresponsive: notify after 1 working day, request a refund after 3 working days, subject to founder approval.',true),
('refunds','What is the refund notification and request timeline?','Notify after 1 working day of unresponsiveness; request the refund after 3 working days, a 3-working-day window with founder approval.',true),
('refunds','How long after approval is a refund paid out?','7 to 14 working days after approval.',true),
('refunds','Is the full reveal fee refunded, or is something deducted?','A 3% processing deduction is applied to the refund.',true),
('refunds','Who approves refunds at QuotesDone?','The founder; refunds require founder approval.',true),
('refunds','What does QuotesDone recover from an unreachable supplier?','The reveal fee plus a 9% per annum late fee plus an AED 250 admin/claim charge.',true),
('refunds','If my chosen supplier never replies, what is the full process to get my money back?','Notify after 1 working day; after 3 working days request a refund; the founder approves; payout lands 7-14 working days after approval, less a 3% processing deduction. QuotesDone separately recovers the reveal fee + 9%/annum late fee + AED 250 admin from the unresponsive supplier.',true),
('verification','What document must a supplier provide to be verified?','A trade licence; it is the only required document and is OCR-verified.',true),
('verification','How is the trade licence checked?','By OCR verification.',true),
('verification','Besides the trade licence, what else is required for supplier verification?','An SMS-verified mobile number, a completed company profile, and acceptance of the terms.',true),
('verification','Are insurance or ISO certificates required to join?','No. They are optional; providing them only widens a supplier reach in matching.',true),
('verification','What do optional documents do for a supplier?','They widen the supplier reach (eligible for more/broader matches) but are not required.',true),
('verification','What happens automatically when a licence expires then is renewed?','Expiry auto-pauses matching; renewal auto-restores matching for free.',true),
('matching','How does QuotesDone match RFQs to suppliers?','With a keyword + capability engine that matches RFQs to relevant verified suppliers.',true),
('matching','Is matching done manually by staff?','No, it is an automated keyword and capability matching engine.',true),
('matching','What can broaden the range of RFQs a supplier is matched to?','Adding optional documents (insurance, ISO) widens reach; a valid trade licence keeps matching active.',true),
('matching','What stops a supplier from being matched to new RFQs?','An expired trade licence auto-pauses matching until valid again.',true),
('matching','Does matching consider only keywords?','No, it is a keyword and capability engine, so it considers both keywords and supplier capabilities.',true),
('quote-quality','Are supplier quotes scored?','Yes. Quote quality is scored, with 70 as the passing threshold.',true),
('quote-quality','What score does a quote need to pass?','70.',true),
('quote-quality','What happens to a quote that scores below the passing threshold?','Not explicitly detailed in canon beyond it not passing (below 70 fails the quality bar). Exact handling of a failing quote is not specified.',true),
('quote-quality','Why does QuotesDone score quote quality?','To ensure buyers receive quality quotes; a passing score (70) supports trust in the anonymised marketplace.',true),
('trust','How does QuotesDone protect buyers from being spammed by suppliers?','Through anonymity; supplier identities stay hidden until a paid reveal, so suppliers cannot contact and spam buyers directly.',true),
('trust','How does QuotesDone protect a buyer from retaliation by their current supplier?','Anonymity hides the buyer identity, preventing an incumbent supplier from retaliating against a buyer who shops around.',true),
('trust','What recourse does a buyer have if a revealed supplier ghosts them?','A refund of the reveal fee via the unresponsive-supplier process (notify after 1wd, request after 3wd, founder approval, payout 7-14wd, 3% deduction).',true),
('trust','How does QuotesDone ensure suppliers are legitimate?','Every supplier is verified via an OCR-checked trade licence plus SMS-verified mobile, company profile, and accepted terms before approval.',true),
('trust','How does QuotesDone handle a supplier that took a reveal but will not respond or pay?','It recovers the reveal fee plus a 9% per annum late fee plus an AED 250 admin/claim charge from the unresponsive supplier.',true),
('brand','What are QuotesDone''s brand colors?','Teal #14B8A6, gold #E3C065, and navy #0C2330.',true),
('brand','What is QuotesDone''s brand typeface?','Poppins.',true),
('brand','What does the QuotesDone logo look like?','A teal ring with a gold check (teal-ring/gold-check logo).',true),
('brand','What is QuotesDone''s teal hex value?','#14B8A6.',true),
('brand','What is QuotesDone''s navy hex value?','#0C2330.',true),
('operating-model','How is QuotesDone run as a company?','As an AI-native company organised into 10 departments, with the founder approving only a limited set of decisions.',true),
('operating-model','How many departments does QuotesDone have?','10.',true),
('operating-model','Which decisions does the founder personally approve?','Only three: marketing posts, ad-boost budgets, and refunds.',true),
('operating-model','Does the founder approve every supplier verification or every RFQ match?','No. The founder approves only marketing posts, ad-boost budgets, and refunds; verification and matching are automated.',true),
('operating-model','Is QuotesDone a human-heavy or AI-native operation?','AI-native; it runs as an AI-native company across 10 departments with minimal founder approvals.',true),
('tech','What is QuotesDone built on?','Supabase and Next.js.',true),
('tech','Which cloud region does QuotesDone run in?','ap-southeast-1.',true),
('tech','How are payments processed?','Via Stripe; QuotesDone never holds supplier bank details.',true),
('tech','Does QuotesDone use a custom backend database or a managed platform?','A managed platform, Supabase (with Next.js on the frontend), hosted in region ap-southeast-1.',true),
('status','Has QuotesDone launched yet?','No, it is pre-launch.',true),
('status','How many UAE supplier records has QuotesDone indexed?','About 20,465 indexed UAE supplier records.',true),
('status','What is the initial launch focus?','Three Dubai trades.',true),
('status','How many suppliers get free registration, and what is the current status of the paid tier?','The first 1,000 suppliers register free; the AED 1,000/year paid tier is currently dormant.',true),
('edge-cases','What if two suppliers quote the exact same price?','Not specified in canon. There is no stated tie-breaking rule; quotes are scored for quality (70 to pass) and reach the buyer anonymised, but identical-price handling is not defined.',true),
('edge-cases','Can a supplier pay to boost their quote above others in the buyer''s view?','Not specified in canon. Ad-boost budgets exist as a founder-approved item, but there is no stated mechanism for suppliers to pay to rank their individual quote higher; quotes are quality-scored.',true),
('edge-cases','If I reveal a supplier and they respond promptly, can I still get a refund?','No. Refunds apply when a revealed supplier is unresponsive; a responsive supplier does not meet the refund condition.',true),
('edge-cases','Can a supplier register with an expired trade licence?','Verification requires a valid OCR-verified trade licence; an expired licence auto-pauses matching and would restore free on renewal, so an expired licence does not sustain active participation.',true);
